#!/usr/bin/env node
// Every `overrides` rule in package.json must hold in the lockfile. npm applies
// overrides when it places a package, so a lockfile regenerated by a tool that
// does not honor them (Dependabot's updater, 2026-10-21: the Angular 22.2.3
// bump re-nested @angular/build's exact vite 8.3.0 pin under sample 12) keeps
// a version the override exists to exclude, and nothing else notices until the
// next advisory. Nested rules (`"@angular/build": { "vite": "^8.3.3" }`) are
// checked by their innermost package name: the range is what matters, not the
// path the rule was written under.
import { readFileSync } from 'node:fs';

const pkg = JSON.parse(readFileSync('package.json', 'utf8'));
const lock = JSON.parse(readFileSync('package-lock.json', 'utf8'));

function collectRules(overrides, rules = new Map()) {
  for (const [name, value] of Object.entries(overrides ?? {})) {
    if (typeof value === 'string') {
      rules.set(name, value);
    } else {
      collectRules(value, rules);
    }
  }
  return rules;
}

function parse(version) {
  const match = /^(\d+)\.(\d+)\.(\d+)/.exec(version);
  if (!match) throw new Error(`cannot parse version "${version}"`);
  return match.slice(1, 4).map(Number);
}

function compare(a, b) {
  for (let i = 0; i < 3; i += 1) {
    if (a[i] !== b[i]) return a[i] - b[i];
  }
  return 0;
}

// The overrides here are caret ranges at the first fixed version, or an exact
// version; anything else is a reason to extend this check, not to skip it.
function satisfies(version, range) {
  const caret = /^\^(\d+\.\d+\.\d+)$/.exec(range);
  const atLeast = /^>=(\d+\.\d+\.\d+)$/.exec(range);
  const actual = parse(version);
  if (caret) {
    const floor = parse(caret[1]);
    return compare(actual, floor) >= 0 && actual[0] === floor[0];
  }
  if (atLeast) return compare(actual, parse(atLeast[1])) >= 0;
  if (/^\d+\.\d+\.\d+$/.test(range)) return compare(actual, parse(range)) === 0;
  throw new Error(`override range "${range}" is not a caret, >= or exact range`);
}

const rules = collectRules(pkg.overrides);
const failures = [];
let checked = 0;
for (const [path, entry] of Object.entries(lock.packages)) {
  const name = entry.name ?? path.slice(path.lastIndexOf('node_modules/') + 'node_modules/'.length);
  if (!path.includes('node_modules/') || !rules.has(name)) continue;
  checked += 1;
  const range = rules.get(name);
  if (!satisfies(entry.version, range)) {
    failures.push(`${path} is ${entry.version}, the override says ${range}`);
  }
}

for (const failure of failures) console.error(`check-overrides: FAIL ${failure}`);
if (failures.length > 0) {
  console.error(
    'check-overrides: re-resolve with `npm update <package> --workspaces --include-workspace-root` (GUIDELINES_NEST_TRPC.md, Audit scope)',
  );
  process.exit(1);
}
console.log(`check-overrides: ok — ${checked} lockfile entries satisfy ${rules.size} override rules`);
